import * as ecs from "@8thwall/ecs";

import { gameData } from "../core/game-data";

import {
  OBJECT_PLACED_EVENT,
} from "./placement-system";


// --------------------------------------------------
// Spawn System
//
// Responsibilities:
// - Listen for DriveZone placement
// - Find TruckSpawnPoint inside prefab
// - Spawn truck
// - Store truckEid
// --------------------------------------------------


ecs.registerComponent({

  name:"spawn-system",


  schema:{

    truckPrefab:ecs.eid,

    truckSpawnPoint:ecs.eid,

  },


  stateMachine:({world,eid,schemaAttribute,defineState})=>{


    defineState("ready")

    .initial()


    .onEnter(()=>{


      console.log(
        "[Spawn] System ready"
      );



      world.events.addListener(

        world.events.globalId,

        OBJECT_PLACED_EVENT,


        ()=>{


          spawnTruck(

            world,

            schemaAttribute.get(eid)

          );


        }

      );


    });


  },


});




// --------------------------------------------------
// Spawn Truck
// --------------------------------------------------

function spawnTruck(

  world:ecs.World,

  schema:any

){


  if(!gameData.driveZoneEid){

    console.error(
      "[Spawn] No DriveZone"
    );

    return;

  }



  if(gameData.truckPlaced)
    return;



  //---------------------------------------
  // Find runtime spawn point
  //---------------------------------------

  const runtimeSpawnPoint =

    world.getInstanceEntity(

      gameData.driveZoneEid,

      schema.truckSpawnPoint

    );



  if(!runtimeSpawnPoint){

    console.error(
      "[Spawn] Missing TruckSpawnPoint"
    );

    return;

  }




  //---------------------------------------
  // Create truck
  //---------------------------------------

  const truck =

    world.createEntity(

      schema.truckPrefab

    );



  const position =

    world.transform.getWorldPosition(

      runtimeSpawnPoint

    );



  world.transform.setWorldPosition(

    truck,

    {

      x:position.x,

      y:position.y,

      z:position.z,

    }

  );



  //---------------------------------------
  // Match track orientation
  //---------------------------------------

  const rotation =

    world.transform.getWorldQuaternion(

      runtimeSpawnPoint

    );



  world.transform.setWorldRotation(

    truck,

    rotation

  );




  //---------------------------------------
  // Store game state
  //---------------------------------------

  gameData.truckEid =
    truck;


  gameData.truckPlaced =
    true;


  gameData.truckSpeed =
    0;


  gameData.truckHeading =
    0;



  console.log(

    "[Spawn] Truck spawned at TruckSpawnPoint",

    truck

  );


}
